CREATE TABLE article_i18n ( article_id INTEGER NOT NULL REFERENCES articles(id) ON DELETE CASCADE, lang TEXT NOT NULL REFERENCES languages(code), slug TEXT NOT NULL, title TEXT NOT NULL, excerpt TEXT NOT NULL DEFAULT '', body_html TEXT NOT NULL DEFAULT '', ready INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (article_id, lang), UNIQUE (lang, slug) ); CREATE TABLE article_tags ( article_id INTEGER NOT NULL REFERENCES articles(id) ON DELETE CASCADE, tag_id INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY (article_id, tag_id) ); CREATE TABLE reviews ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, country_code TEXT, stars INTEGER NOT NULL DEFAULT 5 CHECK (stars BETWEEN 1 AND 5), tour_id INTEGER REFERENCES tours(id) ON DELETE SET NULL, visible INTEGER NOT NULL DEFAULT 1, featured INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) ); CREATE TABLE review_i18n ( review_id INTEGER NOT NULL REFERENCES reviews(id) ON DELETE CASCADE, lang TEXT NOT NULL REFERENCES languages(code), quote TEXT NOT NULL, PRIMARY KEY (review_id, lang) ); CREATE TABLE faq_items ( id INTEGER PRIMARY KEY, sort_order INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 1 ); CREATE TABLE faq_i18n ( faq_id INTEGER NOT NULL REFERENCES faq_items(id) ON DELETE CASCADE, lang TEXT NOT NULL REFERENCES languages(code), question TEXT NOT NULL, answer_html TEXT NOT NULL DEFAULT '', PRIMARY KEY (faq_id, lang) ); CREATE TABLE pages ( id INTEGER PRIMARY KEY, key TEXT NOT NULL UNIQUE ); CREATE TABLE page_i18n ( page_id INTEGER NOT NULL REFERENCES pages(id) ON DELETE CASCADE, lang TEXT NOT NULL REFERENCES languages(code), slug TEXT NOT NULL DEFAULT '', title TEXT NOT NULL DEFAULT '', intro TEXT NOT NULL DEFAULT '', body_html TEXT NOT NULL DEFAULT '', ready INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (page_id, lang), UNIQUE (lang, slug) ); CREATE TABLE seo ( id INTEGER PRIMARY KEY, owner_type TEXT NOT NULL CHECK (owner_type IN ('tour', 'article', 'page')), owner_id INTEGER NOT NULL, lang TEXT NOT NULL REFERENCES languages(code), title TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', focus_keyword TEXT NOT NULL DEFAULT '', canonical_url TEXT NOT NULL DEFAULT '', og_media_id INTEGER REFERENCES media(id) ON DELETE SET NULL, noindex INTEGER NOT NULL DEFAULT 0, UNIQUE (owner_type, owner_id, lang) ); CREATE TRIGGER seo_after_tour_delete AFTER DELETE ON tours BEGIN DELETE FROM seo WHERE owner_type = 'tour' AND owner_id = OLD.id; END; CREATE TRIGGER seo_after_article_delete AFTER DELETE ON articles BEGIN DELETE FROM seo WHERE owner_type = 'article' AND owner_id = OLD.id; END; CREATE TRIGGER seo_after_page_delete AFTER DELETE ON pages BEGIN DELETE FROM seo WHERE owner_type = 'page' AND owner_id = OLD.id; END; CREATE TABLE requests ( id INTEGER PRIMARY KEY, ref TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'confirmed', 'done', 'cancelled')), name TEXT NOT NULL, email TEXT NOT NULL, whatsapp TEXT NOT NULL DEFAULT '', country_code TEXT, lang TEXT NOT NULL DEFAULT 'en' REFERENCES languages(code), tour_id INTEGER REFERENCES tours(id) ON DELETE SET NULL, tour_title TEXT NOT NULL DEFAULT '', preferred_date TEXT, start_time TEXT NOT NULL DEFAULT '', guests INTEGER NOT NULL DEFAULT 2 CHECK (guests >= 1), pickup TEXT NOT NULL DEFAULT '', message TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', price_total INTEGER, deposit_amount INTEGER, deposit_received INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) ); CREATE INDEX requests_status_date ON requests (status, preferred_date); CREATE INDEX requests_created ON requests (created_at DESC); CREATE TABLE request_events ( id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL REFERENCES requests(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK (type IN ('created', 'status', 'note', 'deposit')), from_status TEXT, to_status TEXT, note TEXT NOT NULL DEFAULT '', actor TEXT NOT NULL DEFAULT 'guest', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) ); CREATE INDEX request_events_request ON request_events (request_id, created_at); CREATE TABLE settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) ); CREATE INDEX tours_published ON tours (published, sort_order);
